<!-- CLIENT JAVASCRIPT MICRO-INTERACTIONS -->
<script>
  // FAQ Accordion Controller
  function toggleFaq(btn) {
    const content = btn.nextElementSibling;
    const chevron = btn.querySelector('.relakita-faq-chevron');
    const isOpen = content.style.maxHeight && content.style.maxHeight !== '0px';

    // Close all other items first for neat single-open behavior
    document.querySelectorAll('.relakita-faq-content').forEach(c => {
      c.style.maxHeight = '0px';
    });
    document.querySelectorAll('.relakita-faq-chevron').forEach(i => {
      i.style.transform = 'rotate(0deg)';
    });

    if (!isOpen) {
      content.style.maxHeight = content.scrollHeight + 'px';
      chevron.style.transform = 'rotate(180deg)';
    }
  }

  // Auto-fill and scroll to form when program card button is clicked
  function pilihProgram(namaProgram) {
    const select = document.getElementById('pilihanKlaster');
    if (select) {
      select.value = namaProgram;
    }
    const formSection = document.getElementById('daftar');
    if (formSection) {
      formSection.scrollIntoView({ behavior: 'smooth' });
    }
  }

  // Handle Volunteer Form Submission
  function handleFormSubmit(event) {
    event.preventDefault();
    const btn = document.getElementById('btnSubmitForm');
    const alertBox = document.getElementById('formSuccessAlert');

    btn.disabled = true;
    btn.innerHTML = `<span class="material-symbols-outlined text-[20px] animate-spin">refresh</span> <span>Mengirim Data...</span>`;

    setTimeout(() => {
      btn.disabled = false;
      btn.innerHTML = `<span class="material-symbols-outlined text-[20px]">check</span> <span>Pendaftaran Terkirim!</span>`;
      alertBox.classList.remove('hidden');
      document.getElementById('volunteerForm').reset();

      setTimeout(() => {
        btn.innerHTML = `<span class="material-symbols-outlined text-[20px]">send</span> <span>Kirim Pendaftaran Relawan</span>`;
      }, 5000);
    }, 1000);
  }

  // AI Modal Controller & Hooks into App Shell button
  function openAiModal() {
    const modal = document.getElementById('aiModalBackdrop');
    if (modal) {
      modal.classList.remove('hidden');
      modal.classList.add('flex');
    }
  }

  function closeAiModal() {
    const modal = document.getElementById('aiModalBackdrop');
    if (modal) {
      modal.classList.add('hidden');
      modal.classList.remove('flex');
    }
  }

  // Attach open trigger to shell AI button
  document.addEventListener('DOMContentLoaded', () => {
    const shellAiButton = Array.from(document.querySelectorAll('button'))
      .find(el => el.textContent.includes('Tanya AI Relawan'));
    if (shellAiButton) {
      shellAiButton.addEventListener('click', openAiModal);
    }

    // Connect Shell Navigation links to smooth anchor scroll
    const navLinks = document.querySelectorAll('header nav a, header a[data-path="beranda"]');
    navLinks.forEach(link => {
      link.addEventListener('click', (e) => {
        const path = link.getAttribute('data-path');
        let targetId = '';
        if (path === 'beranda') targetId = 'beranda';
        if (path === 'tentang-kami') targetId = 'tentang';
        if (path === 'program-relawan') targetId = 'program';
        if (path === 'faq') targetId = 'faq';
        if (path === 'kontak' || path === 'daftar-relawan') targetId = 'daftar';

        if (targetId && document.getElementById(targetId)) {
          e.preventDefault();
          document.getElementById(targetId).scrollIntoView({ behavior: 'smooth' });
        }
      });
    });
  });

  // AI Chat Simulation
  function sendQuickPrompt(text) {
    const input = document.getElementById('aiUserInput');
    input.value = text;
    sendAiMessage();
  }

  function sendAiMessage() {
    const input = document.getElementById('aiUserInput');
    const query = input.value.trim();
    if (!query) return;

    const chatBox = document.getElementById('chatMessages');

    // User Message bubble
    const userDiv = document.createElement('div');
    userDiv.className = 'flex items-start gap-2 max-w-[85%] self-end flex-row-reverse';
    userDiv.innerHTML = `
      <div class="w-8 h-8 rounded-full bg-relakita-primary flex items-center justify-center shrink-0 text-relakita-on-primary text-[16px]">
        <span class="material-symbols-outlined text-[18px]">person</span>
      </div>
      <div class="rounded-2xl rounded-tr-none bg-relakita-primary text-relakita-on-primary p-3.5 shadow-sm font-relakita-body-sm text-relakita-body-sm">
        <span data-user-message></span>
      </div>
    `;
    userDiv.querySelector('[data-user-message]').textContent = query;
    chatBox.appendChild(userDiv);
    input.value = '';
    chatBox.scrollTop = chatBox.scrollHeight;

    // Simulated Bot Reply
    setTimeout(() => {
      let botResponse = 'Pilihan yang luar biasa! ';
      const lower = query.toLowerCase();
      if (lower.includes('anak') || lower.includes('ajar') || lower.includes('edukasi') || lower.includes('buku')) {
        botResponse += 'Berdasarkan minat Anda, program <strong>Sahabat Belajar Pelosok</strong> di Flores & Halmahera sangat cocok. Anda bisa membantu mengajar literasi kreatif dan bercerita.';
      } else if (lower.includes('lingkungan') || lower.includes('pantai') || lower.includes('mangrove') || lower.includes('alam')) {
        botResponse += 'Anda sangat pas untuk aksi <strong>Tanam Harapan Pesisir</strong> di Muara Gembong! Kegiatan ini diadakan tiap akhir pekan untuk penanaman mangrove dan bersih pantai.';
      } else if (lower.includes('masak') || lower.includes('dapur') || lower.includes('bencana') || lower.includes('makan')) {
        botResponse += 'Jiwa penolong Anda sangat kami butuhkan di klaster <strong>Dapur Kasih & Tanggap Bencana</strong> untuk meracik paket nutrisi hangat bagi warga.';
      } else {
        botResponse += 'Di Relakita, setiap niat baik memiliki ruangnya. Silakan isi form di bagian pendaftaran, dan koordinator kami akan memandu penempatan terbaik sesuai bakat Anda!';
      }

      const botDiv = document.createElement('div');
      botDiv.className = 'flex items-start gap-2 max-w-[85%]';
      botDiv.innerHTML = `
        <div class="w-8 h-8 rounded-full bg-relakita-primary-fixed flex items-center justify-center shrink-0 text-relakita-primary text-[16px]">
          <span class="material-symbols-outlined text-[18px]">smart_toy</span>
        </div>
        <div class="rounded-2xl rounded-tl-none bg-relakita-surface-container-lowest p-3.5 shadow-sm text-relakita-on-surface font-relakita-body-sm text-relakita-body-sm">
          ${botResponse}
        </div>
      `;
      chatBox.appendChild(botDiv);
      chatBox.scrollTop = chatBox.scrollHeight;
    }, 600);
  }
</script></main><div class="fixed bottom-6 left-6 z-40"><button class="flex items-center gap-relakita-space-xs rounded-full bg-relakita-surface-container-lowest px-relakita-space-md py-relakita-space-sm text-relakita-on-surface shadow-[0_12px_32px_-4px_rgba(234,88,12,0.14)] hover:bg-relakita-surface-container-low transition-colors" type="button"><span class="material-symbols-outlined text-relakita-primary text-[20px]">smart_toy</span><span class="font-relakita-label-sm text-relakita-label-sm text-relakita-on-surface font-semibold">Tanya AI Relawan</span></button></div><div class="fixed bottom-6 right-6 z-40"><a class="flex items-center gap-relakita-space-xs rounded-full bg-[#128c7e] px-relakita-space-md py-relakita-space-sm text-white shadow-[0_12px_32px_-4px_rgba(18,140,126,0.25)] hover:brightness-105 transition-all" href="https://wa.me/" rel="noopener noreferrer" target="_blank"><span class="material-symbols-outlined text-white text-[20px]">chat</span><span class="font-relakita-label-sm text-relakita-label-sm text-white font-semibold">Tanya Koordinator</span></a></div><footer class="w-full bg-[#faf3ea] text-relakita-on-surface-variant mt-relakita-space-xl" id="kontak"><div class="max-w-[1280px] mx-auto px-relakita-margin-mobile md:px-relakita-margin py-relakita-space-xl grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-relakita-space-lg"><div class="flex flex-col gap-relakita-space-sm"><div class="flex items-center gap-relakita-space-xs"><span class="font-relakita-headline-sm text-relakita-headline-sm text-relakita-primary">Relakita</span></div><p class="font-relakita-body-sm text-relakita-body-sm text-relakita-on-surface-variant">Gerakan kerelawanan berbasis empati dan aksi nyata. Mengabdi di pelosok nusantara dengan semangat fajar harapan baru.</p><div class="rounded-xl bg-relakita-surface-container-lowest p-relakita-space-sm shadow-[0_4px_12px_-2px_rgba(244,63,94,0.04)]"><span class="font-relakita-label-sm text-relakita-label-sm text-relakita-tertiary block">L